"""The stock record."""
from dataclasses import dataclass


@dataclass
class StockItem:
    sku: str
    name: str
    quantity: int
    reorder_at: int = 5

    def needs_reorder(self):
        return self.quantity <= self.reorder_at

"""Stock reports."""
from inventory.model import StockItem


def low_stock(records: list[StockItem]) -> list[StockItem]:
    """The StockItems at or under their reorder level, by SKU."""
    return sorted((r for r in records if r.needs_reorder()), key=lambda r: r.sku)


def summary(records: list[StockItem]):
    return f"{len(records)} records, {len(low_stock(records))} to reorder"

"""StockItems held in a warehouse."""
from inventory.model import StockItem


class Warehouse:
    def __init__(self):
        self._records = {}

    def add(self, record: StockItem):
        self._records[record.sku] = record

    def find(self, sku) -> StockItem | None:
        return self._records.get(sku)
